const std = @import("std");
const nsir_core = @import("nsir_core.zig");
const Allocator = std.mem.Allocator;
const Complex = std.math.Complex;
const ArrayList = std.ArrayList;
const ArenaAllocator = std.heap.ArenaAllocator;

pub const SelfSimilarRelationalGraph = nsir_core.SelfSimilarRelationalGraph;
pub const Node = nsir_core.Node;
pub const Edge = nsir_core.Edge;
pub const EdgeQuality = nsir_core.EdgeQuality;
pub const EdgeKey = nsir_core.EdgeKey;

var global_gpa = std.heap.GeneralPurposeAllocator(.{}){};
var global_gpa_inited: bool = true;
const global_allocator: Allocator = global_gpa.allocator();
var global_lock: std.Thread.Mutex = .{};

pub const JAIDE_SUCCESS: cint = 0;
pub const JAIDE_ERROR_NULL_POINTER: cint = -1;
pub const JAIDE_ERROR_ALLOCATION: cint = -2;
pub const JAIDE_ERROR_NODE_NOT_FOUND: cint = -3;
pub const JAIDE_ERROR_EDGE_NOT_FOUND: cint = -4;
pub const JAIDE_ERROR_INVALID_QUALITY: cint = -5;
pub const JAIDE_ERROR_OPTIMIZATION_FAILED: cint = -6;
pub const JAIDE_ERROR_INVALID_STRING: cint = -7;
pub const JAIDE_ERROR_OPERATION_FAILED: cint = -8;

pub const CQuantumState = extern struct {
    real: f64,
    imag: f64,
};

pub const CNode = extern struct {
    id: [*:0]const u8,
    id_len: usize,
    type_name: [*:0]const u8,
    type_name_len: usize,
    quantum_real: f64,
    quantum_imag: f64,
    phase: f64,
};

pub const CEdge = extern struct {
    source: [*:0]const u8,
    source_len: usize,
    target: [*:0]const u8,
    target_len: usize,
    weight: f64,
    quality: cint,
    quantum_real: f64,
    quantum_imag: f64,
    fractal_dimension: f64,
};

pub const CGraph = opaque {
    pub fn fromInternal(graph: *SelfSimilarRelationalGraph) *CGraph {
        return @ptrCast(graph);
    }
    pub fn toInternal(self: *CGraph) *SelfSimilarRelationalGraph {
        return @ptrCast(@alignCast(self));
    }
    pub fn toInternalConst(self: *const CGraph) *const SelfSimilarRelationalGraph {
        return @ptrCast(@alignCast(self));
    }
};

pub const OptimizationStatistics = struct {
    iterations_completed: usize,
    moves_accepted: usize,
    moves_rejected: usize,
    best_energy: f64,
    current_energy: f64,
    temperature: f64,
    acceptance_rate: f64,

    pub fn init() OptimizationStatistics {
        return OptimizationStatistics{
            .iterations_completed = 0,
            .moves_accepted = 0,
            .moves_rejected = 0,
            .best_energy = std.math.inf(f64),
            .current_energy = std.math.inf(f64),
            .temperature = 0.0,
            .acceptance_rate = 0.0,
        };
    }

    pub fn updateAcceptanceRate(self: *OptimizationStatistics) void {
        const total_moves = self.moves_accepted + self.moves_rejected;
        if (total_moves > 0) {
            self.acceptance_rate = @as(f64, @floatFromInt(self.moves_accepted)) / @as(f64, @floatFromInt(total_moves));
        } else {
            self.acceptance_rate = 0.0;
        }
    }
};

const StateDelta = struct {
    edge_ptr: *Edge,
    old_weight: f64,
    old_dim: f64,
    node_ptr: *Node,
    old_qre: f64,
    old_qim: f64,
};

pub const EntangledStochasticSymmetryOptimizer = struct {
    temperature: f64,
    cooling_rate: f64,
    max_iterations: usize,
    current_iteration: usize,
    min_temperature: f64,
    initial_temperature: f64,
    reheat_threshold: f64,
    reheat_factor: f64,
    adaptive_cooling: bool,
    batch_size: usize,
    prng: std.rand.DefaultPrng,
    allocator: Allocator,
    arena: ArenaAllocator,
    statistics: OptimizationStatistics,

    const Self = @This();
    const DEFAULT_MIN_TEMP: f64 = 0.0001;
    const DEFAULT_REHEAT_THRESHOLD: f64 = 0.05;
    const DEFAULT_REHEAT_FACTOR: f64 = 1.5;

    pub fn init(base_allocator: Allocator, initial_temp: f64, cooling_rate: f64, max_iterations: usize) Self {
        var seed_bytes: [8]u8 = undefined;
        std.crypto.random.bytes(&seed_bytes);
        const seed = std.mem.readInt(u64, &seed_bytes, .little);

        const safe_initial = if (std.math.isFinite(initial_temp) and initial_temp > 0.0) initial_temp else 10.0;
        const safe_cooling = if (std.math.isFinite(cooling_rate) and cooling_rate > 0.0 and cooling_rate < 1.0) cooling_rate else 0.99;
        const safe_iters = if (max_iterations > 0) max_iterations else 1000;

        var arena = ArenaAllocator.init(base_allocator);

        return Self{
            .temperature = safe_initial,
            .cooling_rate = safe_cooling,
            .max_iterations = safe_iters,
            .current_iteration = 0,
            .min_temperature = DEFAULT_MIN_TEMP,
            .initial_temperature = safe_initial,
            .reheat_threshold = DEFAULT_REHEAT_THRESHOLD,
            .reheat_factor = DEFAULT_REHEAT_FACTOR,
            .adaptive_cooling = true,
            .batch_size = 5,
            .prng = std.rand.DefaultPrng.init(seed),
            .allocator = base_allocator,
            .arena = arena,
            .statistics = OptimizationStatistics.init(),
        };
    }

    pub fn deinit(self: *Self) void {
        self.arena.deinit();
    }

    inline fn clamp01(x: f64) f64 {
        return @max(0.0, @min(1.0, x));
    }

    fn computeEnergy(graph: *const SelfSimilarRelationalGraph) f64 {
        @setFloatMode(.Optimized);
        var energy: f64 = 0.0;

        var edge_iter = graph.edges.iterator();
        while (edge_iter.next()) |entry| {
            for (entry.value_ptr.items) |*edge| {
                if (edge.weight > 0) {
                    energy += edge.weight * edge.fractal_dimension * 1.0;
                }
                const re = edge.quantum_correlation.re;
                const im = edge.quantum_correlation.im;
                energy += (re * re + im * im);
            }
        }

        var node_iter = graph.nodes.iterator();
        while (node_iter.next()) |entry| {
            const node = entry.value_ptr.*;
            const re = node.quantum_state.re;
            const im = node.quantum_state.im;
            energy += (re * re + im * im);
        }

        return energy;
    }

    fn perturbGraphHardcore(self: *Self, graph: *SelfSimilarRelationalGraph, deltas: *ArrayList(StateDelta)) !void {
        const random = self.prng.random();
        const temp_scale = self.temperature * 0.1;

        var edge_list = ArrayList(*Edge).init(self.arena.allocator());
        var node_list = ArrayList(*Node).init(self.arena.allocator());

        var iter = graph.edges.iterator();
        while (iter.next()) |entry| {
            for (entry.value_ptr.items) |*edge| {
                try edge_list.append(edge);
            }
        }

        var niter = graph.nodes.iterator();
        while (niter.next()) |entry| {
            try node_list.append(entry.value_ptr);
        }

        if (edge_list.items.len == 0 or node_list.items.len == 0) return;

        const actual_batch = @min(self.batch_size, edge_list.items.len);
        var i: usize = 0;
        while (i < actual_batch) : (i += 1) {
            const edge_idx = random.uintAtMost(usize, edge_list.items.len - 1);
            const edge = edge_list.items[edge_idx];

            try deltas.append(.{
                .edge_ptr = edge,
                .old_weight = edge.weight,
                .old_dim = edge.fractal_dimension,
                .node_ptr = undefined,
                .old_qre = 0.0,
                .old_qim = 0.0,
            });

            if (random.float(f64) < 0.5) {
                const pert = (random.float(f64) - 0.5) * temp_scale;
                edge.weight = clamp01(edge.weight + pert);
            }

            if (random.float(f64) < 0.3) {
                const pert = (random.float(f64) - 0.5) * temp_scale * 0.5;
                edge.fractal_dimension = @max(0.0, edge.fractal_dimension + pert);
            }
        }

        if (random.float(f64) < 0.2) {
            const node_idx = random.uintAtMost(usize, node_list.items.len - 1);
            const node = node_list.items[node_idx];

            try deltas.append(.{
                .edge_ptr = undefined,
                .old_weight = 0.0,
                .old_dim = 0.0,
                .node_ptr = node,
                .old_qre = node.quantum_state.re,
                .old_qim = node.quantum_state.im,
            });

            const angle = random.float(f64) * 2.0 * std.math.pi;
            const mag = random.float(f64) * temp_scale * 0.2;
            node.quantum_state.re += mag * @cos(angle);
            node.quantum_state.im += mag * @sin(angle);
        }
    }

    fn rollback(self: *Self, deltas: []const StateDelta) void {
        _ = self;
        @setFloatMode(.Optimized);
        for (deltas) |d| {
            if (d.edge_ptr != undefined) {
                d.edge_ptr.weight = d.old_weight;
                d.edge_ptr.fractal_dimension = d.old_dim;
            }
            if (d.node_ptr != undefined) {
                d.node_ptr.quantum_state.re = d.old_qre;
                d.node_ptr.quantum_state.im = d.old_qim;
            }
        }
    }

    inline fn acceptMove(self: *Self, delta_energy: f64) bool {
        @setFloatMode(.Optimized);
        if (delta_energy <= 0.0) return true;
        if (self.temperature < 1e-9) return false;

        const x = -delta_energy / self.temperature;
        if (x < -700.0) return false;

        const acceptance_probability = @exp(x);
        return self.prng.random().float(f64) < acceptance_probability;
    }

    fn coolTemperature(self: *Self) void {
        if (self.adaptive_cooling) {
            var adjusted_rate = self.cooling_rate;
            if (self.statistics.acceptance_rate > 0.6) {
                adjusted_rate *= 0.9;
            } else if (self.statistics.acceptance_rate < 0.1) {
                adjusted_rate *= 0.999;
            }
            adjusted_rate = @max(0.85, @min(0.9999, adjusted_rate));
            self.temperature *= adjusted_rate;
        } else {
            self.temperature *= self.cooling_rate;
        }

        if (self.temperature < self.min_temperature) {
            self.temperature = self.min_temperature;
        }
    }

    pub fn optimize(self: *Self, graph: *SelfSimilarRelationalGraph) !void {
        @setFloatMode(.Optimized);

        self.arena = ArenaAllocator.init(self.allocator);
        defer self.arena.deinit();
        const scratch = self.arena.allocator();

        self.statistics = OptimizationStatistics.init();
        self.temperature = self.initial_temperature;
        self.current_iteration = 0;

        var current_energy = computeEnergy(graph);
        var best_energy = current_energy;

        self.statistics.best_energy = best_energy;
        self.statistics.current_energy = current_energy;
        self.statistics.temperature = self.temperature;
        self.statistics.updateAcceptanceRate();

        var stagnation_counter: usize = 0;
        const stagnation_limit: usize = @max(@as(usize, 1), self.max_iterations / 20);

        var delta_buffer = ArrayList(StateDelta).init(scratch);

        while (self.current_iteration < self.max_iterations) : (self.current_iteration += 1) {
            delta_buffer.clearRetainingCapacity();

            self.perturbGraphHardcore(graph, &delta_buffer) catch |err| {
                _ = err;
                continue;
            };

            const candidate_energy = computeEnergy(graph);
            const delta_energy = candidate_energy - current_energy;

            if (self.acceptMove(delta_energy)) {
                current_energy = candidate_energy;
                self.statistics.moves_accepted += 1;

                if (candidate_energy < best_energy) {
                    best_energy = candidate_energy;
                    self.statistics.best_energy = best_energy;
                    stagnation_counter = 0;
                } else {
                    stagnation_counter += 1;
                }
            } else {
                self.rollback(delta_buffer.items);
                self.statistics.moves_rejected += 1;
                stagnation_counter += 1;
            }

            self.statistics.current_energy = current_energy;
            self.statistics.temperature = self.temperature;
            self.statistics.iterations_completed = self.current_iteration + 1;
            self.statistics.updateAcceptanceRate();

            self.coolTemperature();

            if (stagnation_counter >= stagnation_limit) {
                if (self.temperature < self.initial_temperature * self.reheat_threshold) {
                    self.temperature = @max(self.min_temperature, self.temperature * self.reheat_factor);
                    stagnation_counter = 0;
                }
            }

            if (self.temperature <= self.min_temperature) break;
        }
    }
};

pub const COptimizer = opaque {
    pub fn fromInternal(opt: *EntangledStochasticSymmetryOptimizer) *COptimizer {
        return @ptrCast(opt);
    }
    pub fn toInternal(self: *COptimizer) *EntangledStochasticSymmetryOptimizer {
        return @ptrCast(@alignCast(self));
    }
};

fn cStringToSliceMax(ptr: [*:0]const u8, max_scan: usize) ?[]const u8 {
    var len: usize = 0;
    while (len < max_scan) : (len += 1) {
        if (ptr[len] == 0) break;
    }
    if (len == max_scan) return null;
    return ptr[0..len];
}

fn cStringToNonEmptySliceMax(ptr: [*:0]const u8, max_scan: usize) ?[]const u8 {
    const s = cStringToSliceMax(ptr, max_scan) orelse return null;
    if (s.len == 0) return null;
    return s;
}

fn normalizePhase(phi: f64) f64 {
    if (!std.math.isFinite(phi)) return 0.0;
    const two_pi = 2.0 * std.math.pi;
    var x = @mod(phi, two_pi);
    if (x < 0.0) x += two_pi;
    return x;
}

pub export fn jaide_global_shutdown() callconv(.C) void {
    global_lock.lock();
    defer global_lock.unlock();

    if (global_gpa_inited) {
        _ = global_gpa.deinit();
        global_gpa_inited = false;
    }
}

pub export fn jaide_create_graph() callconv(.C) ?*CGraph {
    global_lock.lock();
    defer global_lock.unlock();

    if (!global_gpa_inited) return null;

    const graph = global_allocator.create(SelfSimilarRelationalGraph) catch return null;
    errdefer global_allocator.destroy(graph);

    graph.* = SelfSimilarRelationalGraph.init(global_allocator);
    return CGraph.fromInternal(graph);
}

pub export fn jaide_destroy_graph(graph: ?*CGraph) callconv(.C) void {
    global_lock.lock();
    defer global_lock.unlock();

    if (graph) |g| {
        const internal = g.toInternal();
        internal.deinit();
        global_allocator.destroy(internal);
    }
}

pub export fn jaide_graph_node_count(graph: ?*CGraph) callconv(.C) cint {
    global_lock.lock();
    defer global_lock.unlock();

    if (graph == null) return 0;
    const internal = graph.?.toInternalConst();
    const n = internal.nodeCount();
    if (n > @as(usize, @intCast(std.math.maxInt(cint)))) return std.math.maxInt(cint);
    return @intCast(n);
}

pub export fn jaide_add_node(
    graph: ?*CGraph,
    id: [*:0]const u8,
    type_name: [*:0]const u8,
) callconv(.C) cint {
    global_lock.lock();
    defer global_lock.unlock();

    if (graph == null) return JAIDE_ERROR_NULL_POINTER;

    const id_slice = cStringToNonEmptySliceMax(id, 65536) orelse return JAIDE_ERROR_INVALID_STRING;
    const type_slice = cStringToSliceMax(type_name, 65536) orelse return JAIDE_ERROR_INVALID_STRING;

    const internal = graph.?.toInternal();

    if (internal.hasNode(id_slice)) return JAIDE_ERROR_OPERATION_FAILED;

    var node = Node.init(
        global_allocator,
        id_slice,
        type_slice,
        1.0,
        0.0,
        0.0,
    ) catch return JAIDE_ERROR_ALLOCATION;

    internal.addNode(node) catch {
        node.deinit();
        return JAIDE_ERROR_OPERATION_FAILED;
    };

    return JAIDE_SUCCESS;
}
